/**
 * R12 optional offline ranking helper. Accepts paths generated by existing R9C.
 * No graph traversal or Worker runtime search is implemented here.
 * Scores are heuristic discovery priority, NEVER theological probabilities.
 */
const clamp = x => Math.max(0,Math.min(1,x));
const epistemic = new Set(['TEXTUAL','LINGUISTIC','EXTERNAL_WORLD','HYPOTHESIS','RECEPTION']);
function unique(values){return [...new Set(values)].sort();}
function allOf(path,field){return unique(path.steps.flatMap(step=>Array.isArray(step[field])?step[field]:[]));}
function jaccard(a,b){const A=new Set(a),B=new Set(b);if(A.size===0&&B.size===0)return 0;let n=0;for(const x of A)if(B.has(x))n++;return n/(A.size+B.size-n||1);}
function geometricMean(v){return Math.exp(v.reduce((sum,x)=>sum+Math.log(x),0)/v.length);}
function pathKey(path){return path.steps.map(s=>s.edge_id+(s.reversed?':reverse':'')).join('>');}

export function scorePath(path,opts={}) {
  if(!path || !Array.isArray(path.steps) || !path.steps.length)throw new TypeError('Nonempty path required');
  const MAX=opts.maxGraphDegree??10000;
  const semantic=path.steps.filter(s=>!s.administrative);
  if(!semantic.length)throw new TypeError('Path with only administrative steps');
  for(const s of path.steps){
    if(!s.edge_id||!s.relation_type||!epistemic.has(s.epistemic_layer))throw new TypeError('Missing typed step');
    if(!s.administrative && (!(s.quality_weight>0)||s.quality_weight>1))throw new RangeError('Quality weight must be within (0,1]');
    if(s.mapping_status==='unsupported'||s.epistemic_layer==='RECEPTION'&&!opts.allowReception)throw new TypeError('Unsupported/reception step in primary path');
  }
  const Q=geometricMean(semantic.map(s=>s.quality_weight))*Math.pow(0.95,Math.max(0,semantic.length-2));
  const freq=semantic.map(s=>clamp(((s.feature_idf??1)-1)/5));
  const D=freq.reduce((a,b)=>a+b,0)/freq.length;
  const types=unique(semantic.map(s=>s.relation_type));
  const T=Math.min(1,types.length/4);
  const hubDegree=semantic.map(s=>Math.max(0,s.intermediate_degree??0));
  const penalty=0.10*hubDegree.reduce((a,n)=>a+Math.min(1,Math.log1p(n)/Math.log1p(MAX)),0)/hubDegree.length;
  const groups=allOf(path,'attestation_groups');
  const hypothesis=semantic.some(s=>s.epistemic_layer==='HYPOTHESIS'||s.epistemic_layer==='EXTERNAL_WORLD'||s.mapping_status==='candidate');
  const priority=clamp(0.45*Q+0.15*D+0.10*T-penalty);
  return {...path,path_key:pathKey(path),
    score_parts:{Q:Number(Q.toFixed(6)),D:Number(D.toFixed(6)),T:Number(T.toFixed(6)),hub_penalty:Number(penalty.toFixed(6))},
    independent_evidence_groups:groups,
    epistemic_status:hypothesis?'EXPLORATORY':'SUPPORTED_STEPS_NOT_ENDPOINT_INTERPRETATION',
    partial_interest:Number(priority.toFixed(6)),
    edge_ids:unique(path.steps.map(s=>s.edge_id)),
    passage_ids:allOf(path,'passage_ids'),relation_types:types};
}
function pathOverlap(a,b){
  return (jaccard(a.edge_ids,b.edge_ids)+jaccard(a.passage_ids,b.passage_ids)+jaccard(a.relation_types,b.relation_types))/3;
}
export function rankDiscoveryDestinations(paths,opts={}) {
  const selectedMax=opts.limit??24,mmrPenalty=opts.mmrPenalty??0.35;
  const scored=paths.map(p=>scorePath(p,opts));
  const grouped=new Map();
  for(const path of scored){
    if(!path.anchor_id||!path.target_id)throw new TypeError('Path needs canonical anchor and target');
    if(path.anchor_id===path.target_id)continue;
    const key=path.anchor_id+'\u001f'+path.target_id;
    if(!grouped.has(key))grouped.set(key,[]);
    if(!grouped.get(key).some(p=>p.path_key===path.path_key))grouped.get(key).push(path);
  }
  const pool=[];
  for(const [key,group] of grouped){
    group.sort((a,b)=>b.partial_interest-a.partial_interest||a.path_key.localeCompare(b.path_key));
    const attestations=unique(group.flatMap(p=>p.independent_evidence_groups));
    const g=attestations.length;
    const C=Math.min(1,Math.log2(Math.max(1,g))/3);
    const best=group[0];
    const interest=clamp(best.partial_interest+0.30*C);
    const exploratory=group.some(p=>p.epistemic_status==='EXPLORATORY');
    pool.push({
      anchor_id:best.anchor_id,target_id:best.target_id,
      best_path_quality:best.score_parts.Q,interest:Number(interest.toFixed(6)),
      convergence:Number(C.toFixed(6)),support_group_count:g,paths:group,
      evidence_status:exploratory?'MIXED_OR_EXPLORATORY':'SUPPORTED_STEPS_NOT_ENDPOINT_INTERPRETATION',
      limitation:'A graph path does not by itself establish that its endpoints symbolize or equal one another.',
    });
  }
  // MMR after grouping paths by destination; preserve alternate routes inside one destination.
  const selected=[];
  while(pool.length && selected.length<selectedMax){
    let bestI=0,bestValue=-Infinity;
    for(let i=0;i<pool.length;i++){
      const candidate=pool[i];
      let maxO=0;
      for(const other of selected) {
        for(const p of candidate.paths)for(const q of other.paths)maxO=Math.max(maxO,pathOverlap(p,q));
      }
      const v=candidate.interest-mmrPenalty*maxO;
      if(v>bestValue || (v===bestValue&&candidate.target_id<pool[bestI].target_id)){bestI=i;bestValue=v;}
    }
    const [next]=pool.splice(bestI,1);
    selected.push({...next,mmr_score:Number(bestValue.toFixed(6))});
  }
  return {results:selected,coverage:pool.length?'ranked_top_n':'complete_candidate_pool',unreturned_destinations:pool.length};
}
